// Parseert DEGIRO-transactiebevestigingen (1 of meerdere orders per mail) naar
// één item per order voor de website. Zelfde logica als de live-workflow, plus:
//  - meerdere orders in één mail ("De volgende orders zijn uitgevoerd")
//  - sortering oud -> nieuw, zodat de laatste order de huidige prijs bepaalt
//  - iShares-ETF's krijgen een eigen ticker (anders vallen ze samen onder ISHARES)

const MONTHS = {
  jan: '01', feb: '02', mrt: '03', apr: '04', mei: '05', jun: '06',
  jul: '07', aug: '08', sep: '09', okt: '10', nov: '11', dec: '12',
};

const STOPWORDS = new Set([
  'ltd', 'plc', 'nv', 'n.v.', 'inc', 'sa', 'ag', 'se', 'class', 'a', 'b',
  'etf', 'ucits', 'dist', 'acc', 'accumulating', 'core', '-', '(usd)', '(eur)',
]);

function deriveTicker(name) {
  // iShares-fondsen: eerste woord is bij allemaal gelijk, dus ook het tweede gebruiken.
  if (/^ishares\b/i.test(name)) {
    const second = (name.split(/\s+/).filter((w) => !STOPWORDS.has(w.toLowerCase()))[1] || '');
    return ('IS' + second.replace(/[^A-Za-z]/g, '').toUpperCase()).slice(0, 6);
  }
  const words = name.split(/\s+/).filter((w) => w && !STOPWORDS.has(w.toLowerCase().replace(/[.,]/g, '')));
  const base = (words[0] || name.replace(/[^A-Za-z]/g, '')).toUpperCase();
  return base.slice(0, 6);
}

const LABELS = [
  'OrderID', 'Transactiedatum', 'ISIN', 'Opdracht', 'Type', 'Beurs', 'Handelsplaats',
  'Aantal', 'Koers', 'Lokale waarde', 'Waarde', 'Wisselkoers', 'AutoFX kosten',
  'Transactiekosten en/of kosten van derden', 'Totale Kosten', 'Totaal',
];

function extractFields(text) {
  const found = [];
  for (const label of LABELS) {
    const idx = text.indexOf(label);
    if (idx !== -1) found.push({ label, start: idx, end: idx + label.length });
  }
  found.sort((a, b) => a.start - b.start);
  const fields = {};
  for (let i = 0; i < found.length; i++) {
    const to = i + 1 < found.length ? found[i + 1].start : text.length;
    fields[found[i].label] = text.slice(found[i].end, to).trim();
  }
  return fields;
}

function extractBody(json) {
  if (typeof json.text === 'string' && json.text.length > 0) return json.text;
  if (typeof json.textPlain === 'string' && json.textPlain.length > 0) return json.textPlain;
  if (json.payload && json.payload.parts) {
    const stack = [...json.payload.parts];
    while (stack.length) {
      const part = stack.shift();
      if (part.mimeType === 'text/plain' && part.body && part.body.data) {
        const b64 = part.body.data.replace(/-/g, '+').replace(/_/g, '/');
        return Buffer.from(b64, 'base64').toString('utf-8');
      }
      if (part.parts) stack.push(...part.parts);
    }
  }
  return typeof json.snippet === 'string' ? json.snippet : '';
}

function extractSubject(json) {
  if (typeof json.subject === 'string') return json.subject;
  if (json.payload && Array.isArray(json.payload.headers)) {
    const h = json.payload.headers.find((h) => h.name && h.name.toLowerCase() === 'subject');
    if (h) return h.value;
  }
  return '';
}

function parseBlock(block, name, subject) {
  const fields = extractFields(block);
  const orderId = (fields['OrderID'] || '').split(' ')[0] || null;
  const isinRaw = (fields['ISIN'] || '').split(' ')[0].toUpperCase();
  const isin = /^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isinRaw) ? isinRaw : null;
  const txDate = fields['Transactiedatum'] || null;
  const opdracht = fields['Opdracht'] || null;
  const aantal = fields['Aantal'] || null;
  const waarde = fields['Waarde'] || null;

  if (!orderId || !txDate || !opdracht || !aantal || !waarde) {
    return { recognized: false, subject, reason: `Geen OrderID/Transactiedatum/Opdracht/Aantal/Waarde gevonden voor "${name}".` };
  }
  const dateMatch = txDate.match(/(\d{1,2}) (\w{3})\w* (\d{4})(?:,?\s*(\d{1,2}:\d{2}(?::\d{2})?))?/);
  const month = dateMatch ? MONTHS[dateMatch[2].toLowerCase()] : null;
  const type = opdracht.toLowerCase().startsWith('koop') ? 'Kopen' : opdracht.toLowerCase().startsWith('verkoop') ? 'Verkopen' : null;
  const quantity = parseInt((aantal || '').replace(/\D/g, ''), 10);
  const waardeMatch = waarde.match(/EUR\s*(-?[\d.,]+)/);
  if (!dateMatch || !month || !type || !quantity || !waardeMatch) {
    return { recognized: false, subject, reason: `Order "${name}" gevonden maar datum/type/aantal/waarde niet leesbaar.` };
  }
  const date = `${dateMatch[3]}-${month}-${dateMatch[1].padStart(2, '0')}`;
  const time = (dateMatch[4] || '00:00:00').padStart(5, '0');
  const waardeEUR = Math.abs(parseFloat(waardeMatch[1].replace(/\./g, '').replace(',', '.')));
  const price = Math.round((waardeEUR / quantity) * 10000) / 10000;
  return {
    recognized: true, orderId, isin, date, ticker: deriveTicker(name), name, type, quantity, price,
    sortKey: `${date} ${time}`, subject,
  };
}

const results = [];
for (const item of items) {
  const subject = extractSubject(item.json);
  const body = extractBody(item.json).replace(/&amp;/g, '&').replace(/\s+/g, ' ');

  // Elke order begint met "<naam> OrderID"; de naam staat na "uitgevoerd:" of na het "Totaal"-bedrag van de vorige order.
  const re = /(?:uitgevoerd:|Totaal EUR\s*-?[\d.,]+)\s+(.+?)\s+OrderID\s/g;
  const starts = [];
  let m;
  while ((m = re.exec(body)) !== null) {
    starts.push({ name: m[1].trim(), from: m.index + m[0].length - 'OrderID '.length, at: m.index });
  }
  if (!starts.length) {
    results.push({ json: { recognized: false, subject, reason: 'Geen order (naam + OrderID) gevonden in de mail.' } });
    continue;
  }
  for (let i = 0; i < starts.length; i++) {
    const to = i + 1 < starts.length ? starts[i + 1].at : body.length;
    results.push({ json: parseBlock(body.slice(starts[i].from, to), starts[i].name, subject) });
  }
}

// Oud -> nieuw (niet-herkende items achteraan).
results.sort((a, b) => {
  if (a.json.recognized !== b.json.recognized) return a.json.recognized ? -1 : 1;
  return String(a.json.sortKey || '').localeCompare(String(b.json.sortKey || ''));
});
return results;

